// Valida y normaliza el cuerpo del webhook. Nunca confía en lo que envía el cliente.
const body = $('Recibir solicitud').first().json.body ?? {};
const errores = [];
const recortar = (valor, max) => String(valor ?? '').trim().slice(0, max);

const items = Array.isArray(body.items) ? body.items.slice(0, 20) : [];
const carrito = items
  .filter((it) => it && typeof it === 'object')
  .map((it) => ({
    producto_id: Number.isInteger(Number(it.producto_id)) ? Number(it.producto_id) : null,
    nombre: recortar(it.nombre, 120),
    categoria: recortar(it.categoria, 60),
    cantidad: Number.isInteger(it.cantidad) && it.cantidad > 0 ? Math.min(it.cantidad, 999) : 1,
  }))
  .filter((it) => it.nombre);

let productoNuevo = null;
if (body.producto_nuevo && typeof body.producto_nuevo === 'object') {
  productoNuevo = {
    nombre: recortar(body.producto_nuevo.nombre, 120),
    categoria: recortar(body.producto_nuevo.categoria, 60),
    descripcion: recortar(body.producto_nuevo.descripcion, 500),
    precio: Number(body.producto_nuevo.precio) > 0 ? Number(body.producto_nuevo.precio) : null,
  };
  if (!productoNuevo.nombre) errores.push('producto_nuevo.nombre es obligatorio');
}

if (carrito.length === 0 && !productoNuevo) {
  errores.push('Envía "items" con al menos un producto { nombre, ... } o un "producto_nuevo"');
}

return [{
  json: {
    valido: errores.length === 0,
    error: errores.join('; '),
    session_id: recortar(body.session_id, 80) || `anonimo-${$execution.id}`,
    entrada: {
      tipo: carrito.length > 0 ? 'carrito' : 'producto_nuevo',
      carrito,
      producto_nuevo: productoNuevo,
    },
  },
}];

// Convierte la salida del orquestador al contrato { ok, data, error } y
// descarta cualquier recomendación que no exista en el catálogo real.
const salida = $('Orquestador').first().json.output ?? '';
const carrito = $('Validar y normalizar entrada').first().json.entrada.carrito;
const catalogo = $('Obtener catálogo').all().map((item) => item.json).filter((p) => p && p.id);
const idsCarrito = new Set(carrito.map((it) => it.producto_id));

const fallo = (mensaje) => [{ json: { status: 502, body: { ok: false, data: null, error: mensaje } } }];

// Con "continuar ante error", el agente devuelve { error } por su salida normal.
if ($('Orquestador').first().json.error) {
  return fallo('El agente de IA no está disponible en este momento. Intenta más tarde.');
}

function extraerJson(texto) {
  if (texto && typeof texto === 'object') return texto;
  const limpio = String(texto).replace(/```(?:json)?/gi, '').trim();
  const inicio = limpio.indexOf('{');
  const fin = limpio.lastIndexOf('}');
  if (inicio === -1 || fin <= inicio) throw new Error('La respuesta no contiene JSON');
  return JSON.parse(limpio.slice(inicio, fin + 1));
}

let respuesta;
try {
  respuesta = extraerJson(salida);
} catch (error) {
  return fallo('El agente devolvió un formato inválido. Intenta de nuevo.');
}

const descripcion = String(respuesta.descripcion_comercial ?? '').trim();
if (!descripcion) return fallo('El agente no generó la descripción comercial.');

const usados = new Set();
const recomendaciones = (Array.isArray(respuesta.recomendaciones) ? respuesta.recomendaciones : [])
  .map((rec) => ({ rec, producto: catalogo.find((p) => p.id === Number(rec?.producto_id)) }))
  .filter(({ producto }) => {
    if (!producto || producto.stock <= 0 || idsCarrito.has(producto.id) || usados.has(producto.id)) return false;
    usados.add(producto.id);
    return true;
  })
  .slice(0, 2)
  .map(({ rec, producto }) => ({
    producto_id: producto.id,
    nombre: producto.nombre,          // datos tomados del catálogo, no del modelo
    categoria: producto.categoria,
    precio: producto.precio,
    stock: producto.stock,
    motivo: String(rec.motivo ?? '').trim().slice(0, 400) || 'Complementa los productos de tu compra.',
  }));

return [{
  json: {
    status: 200,
    body: { ok: true, data: { descripcion_comercial: descripcion.slice(0, 1500), recomendaciones }, error: null },
  },
}];
